// n8n · F12 · nodo "Trabajos TRM" (Code, una vez para todos los elementos).
// TRM oficial de datos.gov.co (no pide clave). A las 7 a. m. carga los últimos 10 días; a mano, desde 2024.
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const hora = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Bogota', hour: 'numeric', hourCycle: 'h23' }).format(new Date()));
const manual = !$input.first().json.timestamp;
if (!manual && hora !== 7) return [];

const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const desde = manual ? '2024-01-01' : sumar(hoy, -10);
const donde = encodeURIComponent(`vigenciahasta >= '${desde}T00:00:00'`);
return [{ json: { fuente: 'trm', tabla: 'trm_diaria', desde, hasta: hoy, sitio: null,
  url: `https://www.datos.gov.co/resource/32sa-8pi3.json?$order=vigenciadesde&$limit=5000&$where=${donde}` } }];

// n8n · F12 · nodo "Filas TRM" (Code, una vez para todos los elementos).
// datos.gov.co devuelve tramos de vigencia (un fin de semana es un solo tramo); aquí se abren en un valor por día.
const t = $('Trabajos TRM').first().json;
const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };

const porDia = new Map();
for (const { json: x } of $input.all()) {
  if (!x || !x.vigenciadesde) continue;
  const valor = Number(x.valor);
  for (let d = x.vigenciadesde.slice(0, 10); d <= x.vigenciahasta.slice(0, 10); d = sumar(d, 1)) {
    if (d >= t.desde && d <= t.hasta) porDia.set(d, valor);
  }
}
const filas = [...porDia].map(([fecha, valor]) => ({ fecha, valor }));
const fechas = filas.map((f) => f.fecha).sort();
if (!filas.length) return [];
return [{ json: { p_tabla: 'trm_diaria', p_desde: fechas[0], p_hasta: fechas[fechas.length - 1], p_filas: filas, p_fuente: 'trm', p_sitio: null } }];

// n8n · F12 · nodo "Trabajos Brevo" (Code, una vez para todos los elementos).
// Cada hora: correos de las automatizaciones de los últimos 3 días y todas las campañas masivas enviadas.
// Corrido a mano: correos de los últimos 30 días (más no cabe en la memoria del plan de n8n junto con el histórico de Google).
// Los eventos se piden día por día (con un día de margen a cada lado, porque Brevo no usa la hora de Bogotá)
// y en páginas de LIMITE; "Filas Brevo" los junta y guarda solo los días del rango.
const BASE = 'https://api.brevo.com/v3';
const LIMITE = 2500;
const PAGINAS = 2; // hasta 5.000 eventos por día; si la última página llega llena, "Filas Brevo" avisa con un error

const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const manual = !$input.first().json.timestamp;
const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };

const desde = sumar(hoy, manual ? -29 : -2);
const eventos = [];
for (let dia = sumar(desde, -1); dia <= hoy; dia = sumar(dia, 1)) {
  for (let p = 0; p < PAGINAS; p++) {
    eventos.push({ json: {
      fuente: 'brevo', tabla: 'brevo_evento_diario', desde, hasta: hoy, sitio: null, dia, pagina: p, ultima: p === PAGINAS - 1, limite: LIMITE,
      url: `${BASE}/smtp/statistics/events?limit=${LIMITE}&offset=${p * LIMITE}&sort=desc&startDate=${dia}&endDate=${dia}`,
    } });
  }
}

const campanas = { json: {
  fuente: 'brevo', tabla: 'brevo_campana', desde: '2000-01-01', hasta: '2100-12-31', sitio: null,
  url: `${BASE}/emailCampaigns?type=classic&status=sent&statistics=globalStats&excludeHtmlContent=true&limit=100&offset=0`,
} };

return [...eventos, campanas];

// n8n · F12 · nodo "Filas Brevo" (Code, una vez para todos los elementos).
// Junta las páginas de eventos de todos los días en una sola carga (mensajes distintos por día, asunto y evento)
// y arma aparte la carga de las campañas masivas.
const trabajos = $('Trabajos Brevo').all();
const respuestas = $input.all();
const dia = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' });

const salida = [];
const grupos = new Map();
let rango = null;

respuestas.forEach((r, i) => {
  const t = trabajos[i].json;
  if (t.tabla === 'brevo_evento_diario') {
    rango = { desde: t.desde, hasta: t.hasta };
    const ev = r.json.events || [];
    if (t.ultima && ev.length >= t.limite) throw new Error(`Brevo tiene más de ${(t.pagina + 1) * t.limite} eventos el ${t.dia}: hay que subir PAGINAS en "Trabajos Brevo"`);
    for (const e of ev) {
      const f = dia.format(new Date(e.date));
      if (f < t.desde || f > t.hasta) continue;
      const k = [f, String(e.subject || '').trim(), e.event].join('\u0001');
      if (!grupos.has(k)) grupos.set(k, new Set());
      grupos.get(k).add(e.messageId || `${e.email}|${e.date}`);
    }
  } else {
    // Campañas masivas enviadas, con sus cifras acumuladas.
    const filas = (r.json.campaigns || []).filter((c) => c.sentDate).map((c) => {
      const s = (c.statistics && c.statistics.globalStats) || {};
      return { fecha: dia.format(new Date(c.sentDate)), campana_id: String(c.id), campana: c.name || '', asunto: c.subject || '',
        enviados: Math.round(s.sent || 0), entregados: Math.round(s.delivered || 0), aperturas: Math.round(s.uniqueViews || 0),
        clics: Math.round(s.uniqueClicks || 0), desuscritos: Math.round(s.unsubscriptions || 0),
        rebotes: Math.round((s.hardBounces || 0) + (s.softBounces || 0)) };
    });
    salida.push({ json: { p_tabla: 'brevo_campana', p_desde: t.desde, p_hasta: t.hasta, p_filas: filas, p_fuente: 'brevo', p_sitio: null } });
  }
});

if (rango) {
  const filas = [...grupos.entries()].map(([k, ids]) => { const [f, asunto, evento] = k.split('\u0001'); return { fecha: f, asunto, evento, mensajes: ids.size }; });
  salida.unshift({ json: { p_tabla: 'brevo_evento_diario', p_desde: rango.desde, p_hasta: rango.hasta, p_filas: filas, p_fuente: 'brevo', p_sitio: null } });
}
return salida;

// Con la lista de campañas arma los pedidos: la analítica de hoy de cada campaña y las páginas de leads calientes.
const BASE = 'https://api.explee.com/public/api/v1/autogtm';
const campanas = $input.first().json.campaigns || [];
return [
  ...campanas.map((c) => ({ json: { tipo: 'analitica', campana_id: String(c.id), campana: c.name || '',
    url: `${BASE}/campaigns/${c.id}/analytics?period=today` } })),
  ...[0, 100, 200, 300, 400].map((offset) => ({ json: { tipo: 'leads', url: `${BASE}/hot-leads?limit=100&offset=${offset}` } })),
];

// Junta las respuestas: una fila por campaña con lo de hoy, y la lista completa de leads calientes.
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const dia = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' });
const pedidos = $('Pedidos Explee').all();
const respuestas = $input.all();
const num = (v) => (v == null || v === '' ? 0 : Number(v) || 0);

// Deja solo lo que escribió la persona: corta el correo citado ("El ... escribió:", "On ... wrote:", líneas con ">").
const propio = (texto) => {
  const lineas = String(texto || '').split(/\r?\n/);
  const fin = lineas.findIndex((l) => /^\s*>/.test(l) || /^\s*(El|On)\s.+(escribió|wrote):?\s*$/i.test(l) || /^\s*(El|On)\s.+\d{4}/.test(l));
  const t = (fin >= 0 ? lineas.slice(0, fin) : lineas).join(' ').replace(/\s+/g, ' ').trim();
  return t.length > 500 ? t.slice(0, 497) + '...' : t;
};

const nombres = {};
const diario = [];
const leads = new Map();
respuestas.forEach((r, i) => {
  const p = pedidos[i].json;
  if (p.tipo === 'analitica') {
    nombres[p.campana_id] = p.campana;
    const a = r.json;
    diario.push({ fecha: hoy, campana_id: p.campana_id, campana: p.campana, enviados: num(a.emails_sent), respuestas: num(a.total_replies),
      leads: num(a.hot_leads), gasto_usd: num(a.spend_usd) });
  } else {
    for (const l of r.json.leads || []) leads.set(String(l.id ?? `${l.email}|${l.company_domain}`), l);
  }
});

const filasLeads = [...leads.entries()].map(([id, l]) => ({
  fecha: l.became_hot_at ? dia.format(new Date(l.became_hot_at)) : null, lead_id: id,
  campana: nombres[l.campaign_id] || String(l.campaign_id || ''), empresa: l.company_name || '', dominio: l.company_domain || '',
  cargo: l.job_title || '', pais: l.country || '', motivo: propio(l.why_hot), nombre: l.name || '', correo: l.email || '',
  linkedin: l.linkedin_url || '', telefono: l.phone || '', nota: l.note || '',
}));

return [
  { json: { p_tabla: 'explee_campana_diario', p_desde: hoy, p_hasta: hoy, p_filas: diario, p_fuente: 'explee', p_sitio: null } },
  { json: { p_tabla: 'explee_lead', p_desde: hoy, p_hasta: hoy, p_filas: filasLeads, p_fuente: 'explee', p_sitio: null } },
];

const BASE = 'https://wiptool.kommo.com/api/v4';
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const manual = !$input.first().json.timestamp;
const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const desde = sumar(hoy, manual ? -364 : -2);
const unix = Math.floor(new Date(desde + 'T00:00:00-05:00').getTime() / 1000); // medianoche de Bogotá
const PAG_LEADS = 4, PAG_EVENTOS = manual ? 20 : 3; // 250 oportunidades y 100 cambios por página

return [
  { json: { tipo: 'etapas', url: `${BASE}/leads/pipelines` } },
  { json: { tipo: 'usuarios', url: `${BASE}/users?limit=250` } },
  ...Array.from({ length: PAG_LEADS }, (_, i) => ({ json: { tipo: 'leads', pagina: i + 1, ultima: i === PAG_LEADS - 1,
    url: `${BASE}/leads?limit=250&page=${i + 1}&with=loss_reason` } })),
  ...Array.from({ length: PAG_EVENTOS }, (_, i) => ({ json: { tipo: 'eventos', pagina: i + 1, ultima: i === PAG_EVENTOS - 1, desde, hasta: hoy,
    url: `${BASE}/events?limit=100&page=${i + 1}&filter[type]=lead_status_changed&filter[created_at][from]=${unix}` } })),
];

// Junta las páginas y arma tres cargas: etapas, oportunidades y cambios de etapa.
const trabajos = $('Trabajos Kommo').all();
const respuestas = $input.all();
const dia = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' });
const fecha = (s) => (s ? dia.format(new Date(s * 1000)) : null);
const iso = (s) => (s ? new Date(s * 1000).toISOString() : null);
const campo = (lead, prueba) => {
  const f = (lead.custom_fields_values || []).find(prueba);
  return f && f.values && f.values[0] ? String(f.values[0].value ?? '') : '';
};

const etapas = [], usuarios = {}, leads = new Map(), eventos = new Map();
let rango = null;
respuestas.forEach((r, i) => {
  const t = trabajos[i].json;
  const e = (r.json && r.json._embedded) || {};
  if (t.tipo === 'etapas') {
    for (const p of e.pipelines || []) {
      for (const s of (p._embedded && p._embedded.statuses) || []) {
        etapas.push({ etapa_id: s.id, embudo_id: p.id, nombre: s.name, orden: s.sort,
          tipo: s.id === 142 ? 'ganada' : s.id === 143 ? 'perdida' : s.type === 1 ? 'entrantes' : 'abierta' });
      }
    }
  } else if (t.tipo === 'usuarios') {
    for (const u of e.users || []) usuarios[u.id] = u.name;
  } else if (t.tipo === 'leads') {
    const lista = e.leads || [];
    if (t.ultima && lista.length >= 250) throw new Error('Kommo tiene más de 1.000 oportunidades: hay que subir PAG_LEADS en "Trabajos Kommo"');
    for (const l of lista) leads.set(l.id, l);
  } else {
    rango = { desde: t.desde, hasta: t.hasta };
    const lista = e.events || [];
    if (t.ultima && lista.length >= 100) throw new Error('Hay más cambios de etapa de los que se piden: hay que subir PAG_EVENTOS en "Trabajos Kommo"');
    for (const ev of lista) eventos.set(ev.id, ev);
  }
});

const filasLeads = [...leads.values()].map((l) => {
  const motivo = l._embedded && l._embedded.loss_reason;
  return {
    fecha: fecha(l.created_at), lead_id: l.id, nombre: l.name || '', embudo_id: l.pipeline_id, etapa_id: l.status_id, valor: Number(l.price) || 0,
    origen: campo(l, (f) => f.field_name === 'Origen'), campana: campo(l, (f) => f.field_name === 'Campaña'),
    utm_source: campo(l, (f) => f.field_code === 'UTM_SOURCE'), utm_campaign: campo(l, (f) => f.field_code === 'UTM_CAMPAIGN'),
    responsable: usuarios[l.responsible_user_id] || '', motivo_perdida: Array.isArray(motivo) ? (motivo[0] && motivo[0].name) || '' : (motivo && motivo.name) || '',
    creado: iso(l.created_at), actualizado: iso(l.updated_at), cerrado: iso(l.closed_at),
  };
});

const estado = (v) => { const x = (v || [])[0]; return x && x.lead_status ? x.lead_status.id : null; };
const filasEventos = [...eventos.values()].map((ev) => ({
  fecha: fecha(ev.created_at), evento_id: String(ev.id), lead_id: ev.entity_id, de_etapa: estado(ev.value_before), a_etapa: estado(ev.value_after),
  momento: iso(ev.created_at),
})).filter((f) => f.a_etapa && rango && f.fecha >= rango.desde && f.fecha <= rango.hasta);

const hoy = dia.format(new Date());
const salida = [
  { json: { p_tabla: 'kommo_etapa', p_desde: hoy, p_hasta: hoy, p_filas: etapas, p_fuente: null, p_sitio: null } },
  { json: { p_tabla: 'kommo_lead', p_desde: hoy, p_hasta: hoy, p_filas: filasLeads, p_fuente: 'kommo', p_sitio: null } },
];
if (rango) salida.push({ json: { p_tabla: 'kommo_cambio_etapa', p_desde: rango.desde, p_hasta: rango.hasta, p_filas: filasEventos, p_fuente: 'kommo', p_sitio: null } });
return salida;
